pm.test('Status code is 200', function () {
  pm.response.to.have.status(200)
})

pm.test('Uptime is a positive or zero number', function () {
  const data = pm.response.json()

  pm.expect(data.uptime).to.be.a('number')
  pm.expect(data.uptime).to.be.at.least(0)
})

pm.test('Memory usage is a positive number', function () {
  const data = pm.response.json()

  pm.expect(data.memoryUsage).to.be.a('number')
  pm.expect(data.memoryUsage).to.be.above(0)
})

pm.test('Doctors count is a non-negative integer', function () {
  const data = pm.response.json()

  pm.expect(Number.isInteger(data.doctorsCount)).to.eql(true)
  pm.expect(data.doctorsCount).to.be.at.least(0)
})

